"""Append cells (from a '# %%' / '# %% [md]' marked file) to a notebook and execute it.
usage: nbtool.py NOTEBOOK CELLFILE
"""
import sys, re
import nbformat
from nbclient import NotebookClient

nbpath, cellfile = sys.argv[1], sys.argv[2]
try:
    nb = nbformat.read(nbpath, as_version=4)
except FileNotFoundError:
    nb = nbformat.v4.new_notebook()
    nb.metadata["kernelspec"] = {"display_name": "Python 3", "language": "python", "name": "python3"}

text = open(cellfile).read()
parts = re.split(r"^# %%(.*)$", text, flags=re.M)
# parts: [pre, marker1, body1, marker2, body2...]
for marker, body in zip(parts[1::2], parts[2::2]):
    body = body.strip("\n")
    if "[md]" in marker:
        nb.cells.append(nbformat.v4.new_markdown_cell(body))
    else:
        nb.cells.append(nbformat.v4.new_code_cell(body))

# strip old outputs, re-execute top to bottom
for c in nb.cells:
    if c.cell_type == "code":
        c.outputs = []
        c.execution_count = None
client = NotebookClient(nb, timeout=600, kernel_name="python3", resources={"metadata": {"path": "/home/analyst/work"}}, allow_errors=True)
client.execute()
nbformat.write(nb, nbpath)

# print outputs of newly added cells only
n_new = len(parts[1::2])
start = len(nb.cells) - n_new
for i, c in enumerate(nb.cells[start:], start):
    print(f"--- cell {i} ({c.cell_type}) ---")
    if c.cell_type != "code":
        continue
    for o in c.outputs:
        if o.output_type == "stream":
            print(o.text)
        elif o.output_type in ("execute_result", "display_data"):
            if "text/plain" in o.data and "image/png" not in o.data:
                print(o.data["text/plain"])
            elif "image/png" in o.data:
                print("[image output]")
        elif o.output_type == "error":
            print("ERROR:", o.ename, o.evalue)

